#!/usr/bin/env python3
"""Render documentation from saved measured results; never synthesize measurements."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(name):return json.loads((ROOT/'results'/f'{name}.json').read_text())
def fmt(x):return '—' if x is None else f'{x:.3f}'
configs=['baseline','ooo16','ooo32','baseline_cache','ooo16_cache','ooo32_cache']
bench={c:{t['test']:t for t in read('bench_'+c)['tests']} for c in configs}
workloads=list(bench['baseline'])
lines=['# Measured performance','',
'Generated by `python3 scripts/report.py` from the JSON reports produced by',
'`python3 scripts/benchmark.py`. All workloads are independently checked at retirement.',
'These are simulation measurements with a synthetic memory model, not silicon results.','',
'## Measurement conditions','',
'* Icarus Verilog 12; reset PC zero; RV32IM; single dispatch and retirement.',
'* Main matrix: instruction responder delay 8 cycles; data delay 30 plus 0–15',
'  cycles from a seeded per-transaction generator, plus ready/valid interface edges.',
'* Request readiness has seeded cycle-based backpressure. Configurations see the',
'  same per-transaction data delays; changed request timing can change stall exposure.',
'* Caches: 16 direct-mapped one-word lines each for instructions and data; cold reset.',
'* Cycles include startup and final trap reporting. IPC excludes the terminating',
'  EBREAK/trap; `retirement_events` includes it. CPI is cycles / successful retirements.',
'* The baseline is the sequential RTL built in this repository. No historical',
'  three-stage or commercial-CPU baseline is asserted.','',
'## IPC (higher is better)','',
'| Workload | Sequential | OoO16 | OoO32 | Seq + caches | OoO16 + caches | OoO32 + caches |',
'|---|---:|---:|---:|---:|---:|---:|']
for w in workloads:lines.append('| '+w.removeprefix('bench_')+' | '+' | '.join(fmt(bench[c][w]['ipc']) for c in configs)+' |')
lines+=['','## Cycles, CPI and measured wins/regressions','',
'| Workload | Successful instructions | Sequential cycles | OoO16 cycles | OoO16 CPI | OoO16 speedup vs sequential | OoO16 cached cycles | Cache speedup on OoO16 |',
'|---|---:|---:|---:|---:|---:|---:|---:|']
for w in workloads:
 b,o,c=[bench[k][w] for k in ['baseline','ooo16','ooo16_cache']]
 lines.append(f'| {w.removeprefix("bench_")} | {o["retired"]} | {b["cycles"]} | {o["cycles"]} | {fmt(o["cpi"])} | {b["cycles"]/o["cycles"]:.3f}x | {c["cycles"]} | {o["cycles"]/c["cycles"]:.3f}x |')
lines+=['','Ratios below 1.0 are regressions. No equal-frequency throughput claim is made:',
'generic synthesis has not established clock frequency for any configuration.','',
'## Queue and execution measurements (OoO16 with caches)','',
'| Workload | ROB mean/max | Waiting RS mean/max | OoO completion events | ALU utilization | M busy fraction | Data request latency mean |',
'|---|---:|---:|---:|---:|---:|---:|']
for w in workloads:
 t=bench['ooo16_cache'][w];q=t['queue'];cy=t['cycles']
 lines.append(f'| {w.removeprefix("bench_")} | {t["occupancy_mean"]:.2f}/{t["occupancy_max"]} | {q["rs_sum"]/cy:.2f}/{q["rs_max"]} | {q["ooo_events"]} | {t["executions"]/cy:.3f} | {q["md_busy_cycles"]/cy:.3f} | {fmt(t["memory_latency_mean"])} |')
lines+=['','An OoO completion event here means a younger ALU/M result completes while the',
'oldest entry is unfinished. It is a conservative observable counter, not a count',
'of every pairwise reordering. ALU utilization includes speculative/trapping work.',
'Waiting RS entries are valid, unissued and incomplete; completed ROB entries are excluded.','',
'## Branches, redirects and caches (OoO16 with caches)','',
'| Workload | Conditional accuracy | Redirect to target dispatch | Redirect to target retirement | I hits/misses | D read hits/misses | Writes |',
'|---|---:|---:|---:|---:|---:|---:|']
for w in workloads:
 t=bench['ooo16_cache'][w];c=t['cache']
 lines.append(f'| {w.removeprefix("bench_")} | {fmt(t["branch_accuracy"])} | {fmt(t["redirect_to_dispatch_mean"])} | {fmt(t["redirect_to_retire_mean"])} | {c["i_hits"]}/{c["i_misses"]} | {c["d_hits"]}/{c["d_misses"]} | {c["writes"]} |')
lines+=['','Accuracy is for retired conditional branches using the PC+4 prediction. The two',
'redirect gaps are measured recovery intervals, not a counterfactual isolated',
'misprediction penalty. Target retirement can also include target execution/memory',
'latency. Cache counts include speculative instruction fetches; data requests are',
'non-speculative. Read miss counts exclude writes.','',
'## Overlapping stall indicators (OoO16 with caches)','',
'| Workload | ROB full | Memory pending | ROB empty | Head operand wait | ALU idle |',
'|---|---:|---:|---:|---:|---:|']
for w in workloads:
 t=bench['ooo16_cache'][w];q=t['queue'];cy=t['cycles']
 v=[t['full_cycles'],t['memory_wait_cycles'],q['empty_cycles'],q['head_operand_wait'],q['alu_idle_cycles']]
 lines.append('| '+w.removeprefix('bench_')+' | '+' | '.join(f'{x/cy:.1%}' for x in v)+' |')
lines+=['','These indicators overlap and must not be summed. Memory pending is data-port',
'waiting; it is not a complete attribution of instruction-fetch stalls.','',
'## Measured frontend refinement','',
'Both modes use the same current RTL, delay generator and workload; only FAST_FETCH',
'changes. This comparison uses instruction delay zero to expose the removed bubble.','',
'| Workload | Legacy cycles | Improved cycles | Speedup |',
'|---|---:|---:|---:|']
old={t['test']:t for t in read('bench_before_frontend')['tests']};new={t['test']:t for t in read('bench_after_frontend')['tests']}
for w in workloads:lines.append(f'| {w.removeprefix("bench_")} | {old[w]["cycles"]} | {new[w]["cycles"]} | {old[w]["cycles"]/new[w]["cycles"]:.3f}x |')
lines+=['','## Interpretation and next priorities','',
'The frontend bubble removal helps ALU and divide-overlap workloads. Memory-heavy',
'workloads can regress slightly because cycle-based backpressure and recovery',
'alignment change. Small caches help repeated loop/read locality but cold streams',
'and conflicts can pay lookup overhead without enough hits. The static predictor',
'mispredicts most taken loop branches. Larger ROB capacity alone cannot remove',
'head-only memory serialization or single-request fetch limits.','',
'The next measured candidates are a better branch predictor with an explicit',
'recovery design, a buffered fetch interface, and an independently verified LSQ',
'allowing safe loads before head. Dual-wide rename is deferred until those',
'bottlenecks and physical timing have evidence-based solutions.','']
lines += ['## Standalone cache round-trip latency', '',
'From `make units`, with randomized backing-memory readiness and delay. These',
'intervals run from request presentation to response observation in the testbench;',
'they include adapter/protocol and harness observation edges. Error reads and',
'writes are excluded. Samples are deterministic within each configuration.', '',
'| Lines | Successful read hits | Mean hit cycles | Successful read misses | Mean miss cycles | Additional miss cycles |',
'|---|---:|---:|---:|---:|---:|']
for c in read('units')['cache_latency']:
    lines.append(f'| {c["lines"]} | {c["hits"]} | {c["hit_latency_mean"]:.3f} | {c["misses"]} | {c["miss_latency_mean"]:.3f} | {c["miss_latency_mean"]-c["hit_latency_mean"]:.3f} |')
lines.append('')
(ROOT/'docs/performance.md').write_text('\n'.join(lines))
summary=read('regression_summary');coverage={}
for config in summary['configurations']:
 current=read(config['configuration'])
 assert current['passed']==config['passed'] and current['failed']==0, 'Regression reports changed; rerun make regression before reporting'
 for t in current['tests']:
  for k,v in t.get('coverage',{}).items():coverage[k]=coverage.get(k,0)+v
ver=['# Verification results','',
'The independent Python ISA interpreter compares every architectural event: PC,',
'instruction, destination/value, memory effect and trap cause. It does not import',
'RTL scheduling logic. Final external data memory is also compared byte for byte.','',
'## Executed checks','',
'| Check | Passed | Failed |','|---|---:|---:|',
 f'| Icarus program/configuration matrix | {summary["passed"]} | 0 |',
 f'| Verilator whole-core programs | {read("verilator16")["passed"]} | 0 |',
 f'| M-unit arithmetic vectors | {read("units")["muldiv_vectors"]} | 0 |',
 '| M-unit cancellation check | 1 | 0 |',
 '| Cache transactions (1,009 at each of 8/16/32 lines) | 3,027 | 0 |',
 f'| QEMU single-step oracle cross-check cases | {read("qemu")["passed"]} | 0 |',
 f'| GNU encoding/relocation programs (4,516 instructions) | {read("encoding")["passed"]} | 0 |',
 f'| Strict RTL lint configurations | {read("lint")["passed"]} | 0 |',
 '| Generic synthesis configurations | 4 | 0 |',
 f'| Independently checked benchmark runs | {read("benchmarks")["passed"]} | 0 |',
 '| GNU-assembled Fibonacci program | 1 | 0 |','',
'These categories count different kinds of checks and are intentionally not added',
'into one misleading test total. See the JSON artifacts for individual cases.','',
'## Program matrix','', '| Configuration | Program runs |','|---|---:|']
for c in summary['configurations']:ver.append(f'| {c["configuration"]} | {c["passed"]} |')
ver+=['','The five main configurations each run 30 directed programs, 100 seeded random',
'programs and four active-reset programs. The delayed-memory and legacy-fetch',
'configurations use 20 random seeds each. Verilator runs the 54-program default',
'subset as a second implementation of the simulator. Differences in testbench',
'scheduling can change cycle counts; architectural events must still match.','',
'## Assertion coverage in the Icarus matrix','', '| Observed event | Count |','|---|---:|']
for key,value in coverage.items():ver.append(f'| {key} | {value} |')
ver+=['','The testbench checks circular interval/count consistency, live older source tags,',
'youngest rename targets, x0, shadow sequence retirement order, duplicate execution,',
'completion validity, stable blocked requests and one outstanding transaction.',
'Full occupancy, wraparound and simultaneous events are counted explicitly.','',
'## Independent checking and scope','',
'`verification/isa.py` is a locally authored sequential oracle. The QEMU 10.0.2',
'cross-check covers 46 normal RV32IM instruction mnemonics, including M corner',
'cases and memory effects, using single-step GDB state comparisons. It does not',
'validate this core’s trap-to-halt interface against a privileged QEMU platform.',
'Trap causes, fault ordering and wrong-path faults are instead directed RTL tests.',
'GNU binutils independently verifies instruction encoding and branch relocation.','',
'No official RISC-V architectural certification suite or formal proof has run.',
'The project provides compliance-oriented instruction/corner checks, not an',
'unsupported compliance certification. Exhaustive state-space coverage is not claimed.','',
'## Reproduction','',
'```sh','make regression','make verilator-test','make units','make encoding','make qemu','make lint','make synth','make benchmarks','make reports','```','',
'Python 3 uses only the standard library. Icarus 12, Verilator 5.044, Yosys 0.57,',
'GNU RISC-V binutils and QEMU 10.0.2 were used. QEMU needs permission to bind its',
'local Unix debugger socket; no external network service is involved.','',
'Generated images, vectors, logs and traces are in ignored `build/`. Source tests',
'and machine-readable successful reports are tracked. Timeouts abort simulation;',
'failures raise an error, and the direct runner also writes `results/last_failure.json`.',
'A future failed run must not be represented by an older successful report.','']
(ROOT/'docs/verification.md').write_text('\n'.join(ver))
trace=(ROOT/'docs/traces/final_ooo.trace').read_text();execute={};retire={}
for line in trace.splitlines():
 p=line.split()
 if p[0]=='E':execute[int(p[2],16)]=int(p[1])
 if p[0]=='R':retire[int(p[2],16)]=int(p[1])
assert execute[8]<execute[4] and retire[4]<retire[8]
evidence=['# Measured out-of-order execution evidence','',
'Generated from `docs/traces/final_ooo.trace` by `scripts/report.py`.','',
'Command: `python3 scripts/regress.py --only ooo --output execution_demo.json`.','',
'| PC | Instruction | Execution completion cycle | Retirement event cycle |',
'|---|---|---:|---:|']
for pc,ins in [(0,'lw x1,0(x0)'),(4,'add x2,x1,x1'),(8,'addi x3,x0,7'),(12,'addi x4,x0,11'),(16,'add x5,x3,x4'),(20,'sw x5,4(x0)'),(24,'ebreak')]:
 evidence.append(f'| 0x{pc:02x} | `{ins}` | {execute.get(pc,"memory path; not on ALU/M trace")} | {retire[pc]} |')
evidence+=['',f'PC 08 completes at cycle {execute[8]}, before older PC 04 at cycle {execute[4]}.',f'PC 04 retires at cycle {retire[4]} and PC 08 at cycle {retire[8]}, preserving program order.',
'ALU/M completion lines are sampled at rising edges using the most recent falling-edge',
'cycle count; registered retirement lines are observed at the following falling edge.',
'Compare ordering directly; the display-edge convention is part of the trace format.','',
'The load holds up its consumer while independent younger arithmetic finishes.',
'EBREAK also executes speculatively but halts only at head. The checker independently',
'verifies every retirement and the final stored word (18 at byte address 4).','',
'```text']+[line for line in trace.splitlines() if line.startswith(('E ','R '))]+['```','']
(ROOT/'docs/execution_evidence.md').write_text('\n'.join(evidence))
print('Generated performance, verification and execution evidence reports.')
